package com.paymesh.backend.chat;
import com.fasterxml.jackson.databind.*;
import java.time.*;
import java.util.*;
/** Reject financially wrong but schema-valid prose by exact finite approved-answer verification. */
public final class ChatResponseValidator {
 private ChatResponseValidator(){}
 public static ChatDtos.Response validate(JsonNode n,com.paymesh.backend.security.accounts.ChatEvidenceBuilder.Snapshot snapshot){try{
  object(n,"correlationId evidenceCollectedAt answer intent evidenceReferences knowledgeReferences limitations suggestedFollowUps moneyFacts analysisMode generationStatus");var req=snapshot.request();var expected=ChatRules.expected(req);
  require(text(n,"correlationId",36).equals(req.path("correlationId").asText()));require(OffsetDateTime.parse(text(n,"evidenceCollectedAt",40)).toInstant().equals(Instant.parse(req.path("evidence").path("collectedAt").asText())));require(text(n,"intent",32).equals(expected.intent()));
  List<String> refs=strings(n.get("evidenceReferences"),66,80);require(refs.equals(expected.refs()));require(snapshot.references().keySet().containsAll(refs));
  String mode=text(n,"analysisMode",32),status=text(n,"generationStatus",32);JsonNode knowledge=n.get("knowledgeReferences");require(knowledge.isArray()&&knowledge.size()<=5);Set<String> ids=new HashSet<>();List<ChatDtos.Knowledge> kr=new ArrayList<>();String doc=ChatRules.CONTRACT.path("policies").path(expected.topic()).get(0).asText();
  for(JsonNode k:knowledge){object(k,"documentId chunkId title sources score");String did=text(k,"documentId",60),chunk=text(k,"chunkId",120),title=text(k,"title",120);require(did.equals(doc)&&ids.add(chunk));var sources=strings(k.get("sources"),5,200);boolean known=false;for(JsonNode allowed:ChatRules.CONTRACT.path("knowledge"))if(allowed.path("documentId").asText().equals(did)&&allowed.path("chunkId").asText().equals(chunk)&&allowed.path("title").asText().equals(title)&&strings(allowed.get("sources"),5,200).equals(sources))known=true;require(known);require(k.path("score").isNumber());double score=k.path("score").doubleValue();require(Double.isFinite(score)&&score>=0&&score<=1);kr.add(new ChatDtos.Knowledge(did,chunk,title,sources,score));}
  switch(mode){case "DETERMINISTIC"->require(kr.isEmpty()&&Set.of("DISABLED","NOT_ATTEMPTED","NO_RELEVANT_CONTEXT","RETRIEVAL_UNAVAILABLE").contains(status));case "RAG_ASSISTED"->require(!kr.isEmpty()&&Set.of("NOT_ATTEMPTED","DISABLED","TIMEOUT","UNAVAILABLE","INVALID_RESPONSE","VALIDATION_FAILED","CONTEXT_LIMIT").contains(status));case "RAG_LLM"->require(!kr.isEmpty()&&status.equals("SUCCEEDED"));default->throw new IllegalArgumentException();}
  String answer=text(n,"answer",6000);require(answer.equals(expected.answer())||status.equals("SUCCEEDED")&&answer.equals(expected.answer()+ChatRules.CONTRACT.path("explainSuffix").asText()));
  require(strings(n.get("limitations"),16,400).equals(expected.limitations()));List<String> follow=strings(n.get("suggestedFollowUps"),3,120);require(follow.equals(strings(ChatRules.CONTRACT.get("followUps"),3,120)));
  JsonNode facts=n.get("moneyFacts");require(facts.isArray()&&facts.size()<=6&&facts.size()==expected.money().size());List<ChatDtos.Money> money=new ArrayList<>();for(int i=0;i<facts.size();i++){JsonNode f=facts.get(i),e=expected.money().get(i);object(f,"kind amount currency count");for(String key:List.of("kind","amount","currency"))require(text(f,key,80).equals(e.path(key).asText()));Long count=null;if(e.path("count").isNull())require(f.path("count").isNull());else{require(f.path("count").isIntegralNumber()&&f.path("count").canConvertToLong()&&f.path("count").longValue()==e.path("count").longValue());count=f.path("count").longValue();}money.add(new ChatDtos.Money(f.path("kind").asText(),f.path("amount").asText(),f.path("currency").asText(),count));}
  List<String> limits=new ArrayList<>(expected.limitations());limits.addAll(snapshot.limitations());limits.add("This explanation is a dated evidence snapshot, not a live financial instruction or current authorization.");var publicRefs=refs.stream().map(snapshot.references()::get).toList();return new ChatDtos.Response(n.path("correlationId").asText(),answer,expected.intent(),new ChatDtos.Provenance("JAVA_AUTHORIZED_DATABASE_SNAPSHOT",req.path("evidence").path("collectedAt").asText(),req.path("evidence").path("scope").asText(),snapshot.limitations(),snapshot.range()),publicRefs,kr,List.copyOf(limits),follow,money,mode,status);
 }catch(ChatFailure ex){if(ex.status()==422)throw ex;throw invalid();}catch(RuntimeException ex){throw invalid();}}
 private static String text(JsonNode n,String key,int max){JsonNode v=n.get(key);require(v!=null&&v.isTextual()&&!v.asText().isBlank()&&v.asText().codePointCount(0,v.asText().length())<=max);return v.asText();}
 private static List<String> strings(JsonNode n,int max,int chars){require(n!=null&&n.isArray()&&n.size()<=max);List<String> out=new ArrayList<>();for(JsonNode v:n){require(v.isTextual()&&v.asText().length()<=chars);out.add(v.asText());}return out;}
 private static void object(JsonNode n,String fields){require(n!=null&&n.isObject());Set<String> actual=new HashSet<>();n.fieldNames().forEachRemaining(actual::add);require(actual.equals(Set.of(fields.split(" "))));}
 private static void require(boolean valid){if(!valid)throw new IllegalArgumentException();}
 public static ChatFailure invalid(){return new ChatFailure(502,"INVALID_AI_RESPONSE","AI response could not be verified against authorized evidence.");}
}
